package org.example.socialmediabackend.controller;
import org.example.socialmediabackend.model.*;import org.example.socialmediabackend.repository.*;import org.example.socialmediabackend.service.ApiMapper;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/posts") public class PostController {
 private final PostRepository posts;private final UserRepository users;private final PostLikeRepository likes;private final CommentRepository comments;
 public PostController(PostRepository p,UserRepository u,PostLikeRepository likes,CommentRepository comments){posts=p;users=u;this.likes=likes;this.comments=comments;}
 @GetMapping public List<Map<String,Object>> all(Authentication auth){User actor=currentUser(auth);return posts.findAllByOrderByCreatedAtDesc().stream().map(p->ApiMapper.post(p,likes.existsByPostIdAndUserId(p.getId(),actor.getId()))).toList();}
 @GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id,Authentication auth){Post p=findPost(id);User actor=currentUser(auth);return ApiMapper.post(p,likes.existsByPostIdAndUserId(p.getId(),actor.getId()));}
 @GetMapping("/user/{userId}") public List<Map<String,Object>> byUser(@PathVariable Long userId,Authentication auth){User actor=currentUser(auth);return posts.findByUserIdOrderByCreatedAtDesc(userId).stream().map(p->ApiMapper.post(p,likes.existsByPostIdAndUserId(p.getId(),actor.getId()))).toList();}
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object> b,Authentication auth){User actor=users.findByEmailIgnoreCase(auth.getName()).orElseThrow();Object raw=b.get("userId");User owner=actor;if(raw!=null){try{owner=users.findById(Long.parseLong(raw.toString())).orElseThrow();}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Invalid userId"));}}if(!owner.getId().equals(actor.getId()))return ResponseEntity.status(403).body(Map.of("message","You can only create posts for your own account"));String content=Objects.toString(b.getOrDefault("content",b.getOrDefault("caption","")),"").trim();String image=Objects.toString(b.getOrDefault("imageUrl",""),"").trim();if(content.isBlank()&&image.isBlank())return ResponseEntity.badRequest().body(Map.of("message","A post must contain text or an image URL"));if(content.length()>1000)return ResponseEntity.badRequest().body(Map.of("message","Post text cannot exceed 1000 characters"));Post p=new Post();p.setUser(owner);p.setContent(content);p.setImageUrl(image.isBlank()?null:image);return ResponseEntity.status(201).body(ApiMapper.post(posts.save(p),false));}
 @PostMapping("/{id}/like") public Map<String,Object> like(@PathVariable Long id,Authentication auth){Post p=findPost(id);User actor=currentUser(auth);if(likes.existsByPostIdAndUserId(p.getId(),actor.getId())){likes.deleteByPostIdAndUserId(p.getId(),actor.getId());}else{PostLike like=new PostLike();like.setPost(p);like.setUser(actor);likes.save(like);}p.setLikes((int)likes.countByPostId(p.getId()));p=posts.save(p);return ApiMapper.post(p,likes.existsByPostIdAndUserId(p.getId(),actor.getId()));}
 @PostMapping("/{id}/share") public Map<String,Object> share(@PathVariable Long id){Post p=findPost(id);p.setShares(p.getShares()+1);return ApiMapper.post(posts.save(p));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id,Authentication auth){Post p=findPost(id);User actor=users.findByEmailIgnoreCase(auth.getName()).orElseThrow();if(!p.getUser().getId().equals(actor.getId()))return ResponseEntity.status(403).body(Map.of("message","You can only delete your own posts"));comments.deleteByPostId(p.getId());likes.deleteByPostId(p.getId());posts.delete(p);return ResponseEntity.noContent().build();}
 private User currentUser(Authentication auth){return users.findByEmailIgnoreCase(auth.getName()).orElseThrow();}
 private Post findPost(Long id){return posts.findById(id).orElseThrow(()->new org.example.socialmediabackend.exception.ResourceNotFoundException("Post not found: "+id));}
}
